import numpy as np

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    scores = np.full_like(bins, -np.inf, dtype=float)
    if not np.any(valid):
        return scores
    max_cap = np.max(bins) if len(bins) > 0 and np.max(bins) > 0 else 1.0
    used_capacity = max_cap - bins
    mean_used = np.mean(used_capacity[used_capacity > 0]) if np.any(used_capacity > 0) else 0.0
    for i in range(len(bins)):
        if valid[i]:
            if bins[i] == max_cap:
                scores[i] = 1.0 / (1.0 + 2.0 * item)
            else:
                utilization = 1.0 - (remaining[i] / max_cap)
                balance_penalty = abs((max_cap - bins[i]) - mean_used) / max_cap
                scores[i] = utilization - balance_penalty
    return scores
```

